def __node_version(**_extra):
    import json, os, datetime, time, platform, subprocess
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Quota / rate-limit + audit log
    def _enforce_and_log(status, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            usage = {}
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        # Defaults (not specified by schema; use conservative values)
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        day = neon.get("day")
        if not isinstance(day, str) or day != now[:10]:
            neon["day"] = now[:10]
            neon["calls_today"] = 0

        # Count this-minute calls from stored logs (support common timestamp keys)
        window_prefix = now[:16]  # YYYY-MM-DDTHH:MM
        calls_this_min = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str) and ts.startswith(window_prefix):
                calls_this_min += 1

        # Enforce before recording this call as successful; for an exceeded limit we record an error row.
        if status != "error":
            if calls_this_min >= rate_per_min:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append({
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                    "endpoint": "__node_version",
                    "status": "error",
                    "error_code": "RATE_LIMIT",
                    "timestamp": now,
                    "latency_ms": latency_ms,
                })
                _save("request_logs.json", logs)
                usage["neon"] = neon
                _save("usage.json", usage)
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            if int(neon.get("calls_today", 0)) >= quota_per_day:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append({
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                    "endpoint": "__node_version",
                    "status": "error",
                    "error_code": "QUOTA_EXCEEDED",
                    "timestamp": now,
                    "latency_ms": latency_ms,
                })
                _save("request_logs.json", logs)
                usage["neon"] = neon
                _save("usage.json", usage)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "__node_version",
            "status": status,
            "timestamp": now,
            "latency_ms": latency_ms,
        }
        if error_code:
            row["error_code"] = error_code
        if extra:
            row.update(extra)
        logs.append(row)
        # Increment quota counters for all calls (reads included), even errors, like typical API analytics.
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _save("request_logs.json", logs)
        _save("usage.json", usage)
        return None

    # This offline implementation does not gate diagnostics behind internal privileges because
    # there is no auth parameter and ambient auth must resolve to "some authenticated context".
    # If the environment cannot determine Node.js version, return INTERNAL.
    # (The audit defect was returning UNAUTHORIZED for a well-formed call.)
    limiter_err = _enforce_and_log("ok")  # may return RATE_LIMIT/QUOTA_EXCEEDED error object
    if limiter_err:
        return limiter_err

    node_version = None
    node_path = None
    try:
        out = subprocess.check_output(["node", "--version"], stderr=subprocess.STDOUT, timeout=2)
        node_version = out.decode("utf-8", "ignore").strip()
        node_path = "node"
    except FileNotFoundError:
        node_version = None
    except subprocess.TimeoutExpired:
        node_version = None
    except OSError:
        node_version = None

    if not node_version:
        # overwrite last log row status to error with INTERNAL (service couldn't determine)
        logs = _load("request_logs.json")
        if isinstance(logs, list) and logs:
            last = logs[-1]
            if isinstance(last, dict) and last.get("endpoint") == "__node_version" and last.get("status") == "ok":
                last["status"] = "error"
                last["error_code"] = "INTERNAL"
                last["latency_ms"] = int((time.time() - t0) * 1000)
                _save("request_logs.json", logs)
        return _err("INTERNAL", "Node.js version could not be determined in this environment.")

    # return single version payload
    return {
        "node": {
            "version": node_version,
            "binary": node_path,
        },
        "runtime": {
            "python": platform.python_version(),
            "platform": platform.platform(),
        },
        "timestamp": now,
    }

def list_projects(account_id=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "list_projects",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    # usage + rate limit
    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            usage = {}
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        if neon.get("day") != now[:10]:
            neon["day"] = now[:10]
            neon["calls_today"] = 0

        window_prefix = now[:16]
        calls_this_min = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str) and ts.startswith(window_prefix):
                calls_this_min += 1

        if calls_this_min >= rate_per_min:
            _log("error", "RATE_LIMIT")
            usage["neon"] = neon
            _save("usage.json", usage)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            _log("error", "QUOTA_EXCEEDED")
            usage["neon"] = neon
            _save("usage.json", usage)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _save("usage.json", usage)
        return None

    lim_err = _check_limits()
    if lim_err:
        return lim_err

    # Validate inputs
    if account_id is not None and not isinstance(account_id, str):
        _log("error", "VALIDATION_ERROR", field="account_id")
        return _err("VALIDATION_ERROR", "account_id must be a string.", field="account_id")
    allowed_status = ("provisioning", "active", "deleting", "deleted", "error")
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", "VALIDATION_ERROR", field="status")
        return _err("VALIDATION_ERROR", "Invalid status value.", field="status", allowed=list(allowed_status))
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", "VALIDATION_ERROR", field="limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR", field="cursor")
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    allowed_sort = ("created_at", "updated_at", "name")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log("error", "VALIDATION_ERROR", field="sort")
        return _err("VALIDATION_ERROR", "Invalid sort field.", field="sort", allowed=list(allowed_sort))
    allowed_order = ("asc", "desc")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        _log("error", "VALIDATION_ERROR", field="order")
        return _err("VALIDATION_ERROR", "Invalid order value.", field="order", allowed=list(allowed_order))

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Business rule: list_projects returns projects where account_id matches the caller and deleted_at IS NULL.
    # With no auth parameter, "caller" context is ambient; if account_id is provided, scope to it.
    # If account_id is not provided, return all non-deleted projects (visible to caller in this offline store).
    rows = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("deleted_at") is not None:
            continue
        if account_id is not None and p.get("account_id") != account_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        rows.append(p)

    # Sort
    def _key(p):
        v = p.get(sort)
        if v is None:
            return ""
        return v
    reverse = (order == "desc")
    try:
        rows.sort(key=_key, reverse=reverse)
    except TypeError:
        # Fallback stable stringify sort if mixed types
        rows.sort(key=lambda p: str(p.get(sort)), reverse=reverse)

    # Cursor: accept either an opaque base64 JSON {"after": "<id>"} or a direct project id.
    start_index = 0
    if cursor:
        after_id = None
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(decoded.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("after"), str):
                after_id = obj["after"]
        except Exception:
            after_id = cursor  # treat as direct id
        if after_id:
            for i, p in enumerate(rows):
                if p.get("id") == after_id:
                    start_index = i + 1
                    break

    page = rows[start_index:start_index + limit]
    has_more = start_index + limit < len(rows)
    next_cursor = None
    if has_more and page:
        payload = {"after": page[-1].get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok", total=len(rows), returned=len(page))
    return {
        "projects": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        }
    }

def create_project(account_id, name, region, postgres_version, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000,9999)}",
            "endpoint": "create_project",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            usage = {}
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        if neon.get("day") != now[:10]:
            neon["day"] = now[:10]
            neon["calls_today"] = 0
        window_prefix = now[:16]
        calls_this_min = 0
        for r in logs[-5000:]:
            if isinstance(r, dict):
                ts = r.get("timestamp") or r.get("ts")
                if isinstance(ts, str) and ts.startswith(window_prefix):
                    calls_this_min += 1
        if calls_this_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _save("usage.json", usage)
        return None

    lim_err = _check_limits()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    # ---- validation ----
    if not isinstance(account_id, str) or not account_id.strip():
        _log("error", "VALIDATION_ERROR", field="account_id")
        return _err("VALIDATION_ERROR", "account_id is required and must be a string.", field="account_id")
    if not isinstance(name, str) or not name.strip():
        _log("error", "VALIDATION_ERROR", field="name")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    if not isinstance(region, str) or not region.strip():
        _log("error", "VALIDATION_ERROR", field="region")
        return _err("VALIDATION_ERROR", "region is required and must be a non-empty string.", field="region")
    if not isinstance(postgres_version, int) or postgres_version not in (14, 15, 16, 17):
        _log("error", "VALIDATION_ERROR", field="postgres_version")
        return _err("VALIDATION_ERROR", "postgres_version must be one of 14, 15, 16, 17.", field="postgres_version")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    branches = _load("branches.json")
    if not isinstance(branches, list):
        branches = []
    endpoints = _load("database_endpoints.json")
    if not isinstance(endpoints, list):
        endpoints = []

    # Ambient auth: no explicit credential param, so do NOT require accounts.json.
    # Enforce uniqueness: unique(account_id,name) where deleted_at is null.
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("account_id") == account_id and p.get("name") == name and p.get("deleted_at") is None:
            _log("error", "CONFLICT", account_id=account_id)
            return _err("CONFLICT", "A project with this name already exists in the account.", account_id=account_id, name=name)

    # id generator
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _rand(n=26):
            return "".join(random.choice(alphabet) for _ in range(n))
        existing = set()
        if prefix == "neon_prj_":
            existing = {r.get("id") for r in projects if isinstance(r, dict)}
        elif prefix == "neon_br_":
            existing = {r.get("id") for r in branches if isinstance(r, dict)}
        elif prefix == "neon_ep_":
            existing = {r.get("id") for r in endpoints if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{_rand(26)}"
            if cand not in existing:
                return cand
        return f"{prefix}{_rand(30)}"

    project_id = _new_id("neon_prj_")
    branch_id = _new_id("neon_br_")
    endpoint_id = _new_id("neon_ep_")

    # Create project provisioning
    project_row = {
        "id": project_id,
        "account_id": account_id,
        "name": name.strip(),
        "region": region.strip(),
        "postgres_version": int(postgres_version),
        "default_branch_id": None,
        "status": "provisioning",
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Create initial main branch (creating -> ready)
    branch_row = {
        "id": branch_id,
        "project_id": project_id,
        "name": "main",
        "parent_branch_id": None,
        "is_default": True,
        "is_temporary": False,
        "temporary_reason": None,
        "compute_size": None,
        "status": "creating",
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Create initial endpoint (provisioning -> available)
    # Ensure constraint: unique(project_id, branch_id, database_name) where status != deleted.
    # Using default database_name 'neondb' like Neon default.
    ep_row = {
        "id": endpoint_id,
        "project_id": project_id,
        "branch_id": branch_id,
        "database_name": "neondb",
        "default_role": "neondb_owner",
        "host": f"{branch_id}.{project_id}.neon.local",
        "port": 5432,
        "ssl_mode": "require",
        "status": "provisioning",
        "created_at": now,
        "updated_at": now,
    }

    # Persist initial provisioning state
    projects.append(project_row)
    branches.append(branch_row)
    endpoints.append(ep_row)
    _save("projects.json", projects)
    _save("branches.json", branches)
    _save("database_endpoints.json", endpoints)

    # Advance "async" provisioning immediately for offline model:
    # branch creating -> ready, project default_branch_id set, endpoint provisioning -> available, project provisioning -> active
    branch_row["status"] = "ready"
    branch_row["updated_at"] = now
    ep_row["status"] = "available"
    ep_row["updated_at"] = now
    project_row["default_branch_id"] = branch_id
    # Active only after main ready + at least one endpoint available
    project_row["status"] = "active"
    project_row["updated_at"] = now

    _save("projects.json", projects)
    _save("branches.json", branches)
    _save("database_endpoints.json", endpoints)

    _log("ok")
    return {"project": project_row}

def delete_project(project_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "delete_project",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            usage = {}
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        if neon.get("day") != now[:10]:
            neon["day"] = now[:10]
            neon["calls_today"] = 0
        window_prefix = now[:16]
        calls_this_min = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str) and ts.startswith(window_prefix):
                calls_this_min += 1
        if calls_this_min >= rate_per_min:
            _log("error", "RATE_LIMIT")
            usage["neon"] = neon
            _save("usage.json", usage)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            _log("error", "QUOTA_EXCEEDED")
            usage["neon"] = neon
            _save("usage.json", usage)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _save("usage.json", usage)
        return None

    lim_err = _check_limits()
    if lim_err:
        return lim_err

    if not isinstance(project_id, str) or re.match(r"^neon_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id) is None:
        _log("error", "VALIDATION_ERROR", field="project_id")
        return _err("VALIDATION_ERROR", "project_id does not match expected format.", field="project_id",
                    pattern="^neon_prj_[0-9A-HJKMNP-TV-Z]{10,}$")

    projects = _load("projects.json")
    branches = _load("branches.json")
    endpoints = _load("database_endpoints.json")
    if not isinstance(projects, list): projects = []
    if not isinstance(branches, list): branches = []
    if not isinstance(endpoints, list): endpoints = []

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj or proj.get("deleted_at") is not None or proj.get("status") == "deleted":
        _log("error", "NOT_FOUND", project_id=project_id)
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    if proj.get("status") in ("deleting", "deleted"):
        _log("error", "CONFLICT", project_id=project_id)
        return _err("CONFLICT", "Project is already deleting or deleted.", project_id=project_id)

    # Transition project: active/provisioning/error -> deleting -> deleted
    allowed_from = {"provisioning", "active", "error"}
    if proj.get("status") not in allowed_from:
        _log("error", "INVALID_TRANSITION", project_id=project_id)
        return _err("INVALID_TRANSITION", f"Cannot delete project from status '{proj.get('status')}'.", field="status")

    proj["status"] = "deleting"
    proj["updated_at"] = now

    # Cascade: branches -> deleting -> deleted (soft-delete); endpoints -> deleted
    for b in branches:
        if not isinstance(b, dict):
            continue
        if b.get("project_id") != project_id:
            continue
        if b.get("status") == "deleted" or b.get("deleted_at") is not None:
            continue
        # legal transitions: creating/ready/error -> deleting -> deleted
        if b.get("status") in ("creating", "ready", "error"):
            b["status"] = "deleting"
            b["updated_at"] = now
        if b.get("status") == "deleting":
            b["status"] = "deleted"
            b["deleted_at"] = now
            b["updated_at"] = now

    for ep in endpoints:
        if not isinstance(ep, dict):
            continue
        if ep.get("project_id") != project_id:
            continue
        if ep.get("status") == "deleted":
            continue
        ep["status"] = "deleted"
        ep["updated_at"] = now

    # Finish project deletion
    proj["status"] = "deleted"
    proj["deleted_at"] = now
    proj["updated_at"] = now

    _save("projects.json", projects)
    _save("branches.json", branches)
    _save("database_endpoints.json", endpoints)

    _log("ok", project_id=project_id)
    return {"project": proj}

def describe_project(project_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # request logging / rate limiting (best-effort)
    request_logs = _load("request_logs.json")
    usage = _load("usage.json")
    if not isinstance(usage, dict):
        usage = {}
    neon_usage = usage.get("neon")
    if not isinstance(neon_usage, dict):
        neon_usage = {"quota_per_day": 10000, "rate_limit_per_minute": 120, "calls_today": 0, "day": now[:10]}
    # reset daily counter if day changed
    if neon_usage.get("day") != now[:10]:
        neon_usage["day"] = now[:10]
        neon_usage["calls_today"] = 0

    # rate limit: per-minute across all callers (ambient auth)
    window_start = (datetime.datetime.utcnow().replace(second=0, microsecond=0)).isoformat() + "Z"
    calls_this_min = 0
    for r in request_logs[-2000:]:
        if isinstance(r, dict) and r.get("ts", "").startswith(window_start[:16]):  # YYYY-MM-DDTHH:MM
            calls_this_min += 1

    if calls_this_min >= int(neon_usage.get("rate_limit_per_minute", 120)):
        req = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "describe_project",
            "ts": now,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        request_logs.append(req)
        _save("request_logs.json", request_logs)
        usage["neon"] = neon_usage
        _save("usage.json", usage)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    if neon_usage.get("calls_today", 0) >= int(neon_usage.get("quota_per_day", 10000)):
        req = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "describe_project",
            "ts": now,
            "status": "error",
            "error_code": "QUOTA_EXCEEDED",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        request_logs.append(req)
        _save("request_logs.json", request_logs)
        usage["neon"] = neon_usage
        _save("usage.json", usage)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # validation
    if not isinstance(project_id, str) or not re.match(r"^neon_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        status = "error"
        out = _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
    else:
        projects = _load("projects.json")
        branches = _load("branches.json")

        proj = None
        for p in projects:
            if isinstance(p, dict) and p.get("id") == project_id:
                proj = p
                break

        # Visibility rules: must not return deleted unless internal privileges.
        # Ambient auth: if internal privileges exist in store, allow; otherwise hide deleted.
        internal_priv = False
        accounts = _load("accounts.json")
        for a in accounts:
            if isinstance(a, dict) and a.get("internal") is True:
                internal_priv = True
                break

        if proj is None or (proj.get("deleted_at") is not None and not internal_priv):
            status = "error"
            out = _err("NOT_FOUND", "Project not found or not visible")
        else:
            # collect non-deleted branches for this project (Neon-like)
            proj_branches = []
            for b in branches:
                if not isinstance(b, dict):
                    continue
                if b.get("project_id") != project_id:
                    continue
                if b.get("deleted_at") is None:
                    proj_branches.append(b)

            # If project is active, enforce invariant default_branch_id present (otherwise data is inconsistent)
            if proj.get("status") == "active" and not proj.get("default_branch_id"):
                # treat as backend inconsistency; return error rather than fabricating
                status = "error"
                out = _err("CONFLICT", "Project is active but has no default_branch_id")
            else:
                status = "ok"
                out = {
                    "project": proj,
                    "branches": proj_branches,
                    "default_branch_id": proj.get("default_branch_id"),
                }

    neon_usage["calls_today"] = int(neon_usage.get("calls_today", 0)) + 1
    usage["neon"] = neon_usage

    req = {
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": "describe_project",
        "ts": now,
        "status": status,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    if status != "ok":
        req["error_code"] = out["error"]["code"]
    request_logs.append(req)
    _save("request_logs.json", request_logs)
    _save("usage.json", usage)

    return out

