        calls_this_min = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str) and ts.startswith(window_prefix):
                calls_this_min += 1
        if calls_this_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _write_usage(usage)
        return None

    def _log(status_str, error_code=None, **extra):
        logs = _read_logs()
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000,9999)}",
            "endpoint": "get_database_tables",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if extra:
            row.update(extra)
        logs.append(row)
        _write_logs(logs)

    # Validate
    for fld, val in (("project_id", project_id), ("branch_id", branch_id), ("database_name", database_name)):
        if not isinstance(val, str) or not val:
            lim = _check_limits_and_bump()
            if lim:
                _log("error", lim["error"]["code"])
                return lim
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{fld} is required", field=fld)

    if schema_name is not None and not isinstance(schema_name, str):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "schema_name must be a string", field="schema_name")

    if include_views is not None and not isinstance(include_views, bool):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_views must be boolean", field="include_views")
    if include_system_tables is not None and not isinstance(include_system_tables, bool):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_system_tables must be boolean", field="include_system_tables")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500", field="limit")

    allowed_sort = {"schema_name", "-schema_name", "table_name", "-table_name", None}
    if sort not in allowed_sort:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=[s for s in ["schema_name", "-schema_name", "table_name", "-table_name"]])

    lim = _check_limits_and_bump()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    projects = _load("projects.json")
    branches = _load("branches.json")
    endpoints = _load("database_endpoints.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(branches, list):
        branches = []
    if not isinstance(endpoints, list):
        endpoints = []

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj or prj.get("deleted_at") is not None or prj.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found", field="project_id")

    br = next((b for b in branches if isinstance(b, dict) and b.get("id") == branch_id), None)
    if not br or br.get("project_id") != project_id or br.get("deleted_at") is not None or br.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Branch not found for project", field="branch_id")
    if br.get("status") != "ready":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Branch must be ready to list tables", rule="get_database_tables requires branch.status='ready'")

    # ensure an available endpoint exists (rule)
    eps = [e for e in endpoints if isinstance(e, dict) and e.get("project_id") == project_id and e.get("branch_id") == branch_id and e.get("status") == "available"]
    if not eps:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No available endpoint for this project/branch to list tables", rule="get_database_tables requires endpoint.status='available'")

    # Offline catalog: fabricate from prior successful sql_executions and from schema_name/table_name hints.
    execs = _load("sql_executions.json")
    if not isinstance(execs, list):
        execs = []

    tables = {}
    # extract simplistic CREATE TABLE schema.table patterns
    for ex in execs[-2000:]:
        if not isinstance(ex, dict):
            continue
        if ex.get("project_id") != project_id or ex.get("branch_id") != branch_id or ex.get("database_name") != database_name:
            continue
        if ex.get("status") != "succeeded":
            continue
        stmts = ex.get("statements")
        if not isinstance(stmts, list):
            continue
        for s in stmts:
            if not isinstance(s, str):
                continue
            su = s.strip()
            m = su.lower().find("create table")
            if m != -1:
                rest = su[m + len("create table"):].strip()
                # strip "if not exists"
                if rest.lower().startswith("if not exists"):
                    rest = rest[len("if not exists"):].strip()
                token = rest.split()[0].strip('"')
                if "." in token:
                    sch, tbl = token.split(".", 1)
                else:
                    sch, tbl = "public", token
                tables[(sch, tbl)] = {"schema_name": sch, "table_name": tbl, "type": "table"}

    # if none inferred, return an empty list (valid)
    rows = list(tables.values())

    # Apply schema filter
    if schema_name:
        rows = [r for r in rows if r.get("schema_name") == schema_name]

    # Views/system tables toggles: we only have "table" types here; keep behavior consistent.
    if include_views is False:
        rows = [r for r in rows if r.get("type") != "view"]
    if include_system_tables is False:
        rows = [r for r in rows if not (r.get("schema_name") or "").startswith("pg_") and r.get("schema_name") != "information_schema"]

    # Sorting
    if sort in (None, "schema_name"):
        rows.sort(key=lambda r: (r.get("schema_name") or "", r.get("table_name") or ""))
    elif sort == "-schema_name":
        rows.sort(key=lambda r: (r.get("schema_name") or "", r.get("table_name") or ""), reverse=True)
    elif sort == "table_name":
        rows.sort(key=lambda r: (r.get("table_name") or "", r.get("schema_name") or ""))
    elif sort == "-table_name":
        rows.sort(key=lambda r: (r.get("table_name") or "", r.get("schema_name") or ""), reverse=True)

    # Pagination cursor: base64 of integer offset; if invalid, treat as 0 (opaque cursor)
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        try:
            dec = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(dec.decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {"tables": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

def describe_branch(project_id, branch_id, database_name=None, schema_name=None, include_views=None, include_functions=None, **_extra):
    import json, os, datetime, time, random
