    def _write_usage(usage):
        _save("usage.json", usage)

    def _check_limits_and_bump():
        logs = _read_logs()
        usage = _read_usage()
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        day = now[:10]
        if neon.get("day") != day:
            neon["day"] = day
            neon["calls_today"] = 0

        window_prefix = now[:16]
        calls_this_min = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str) and ts.startswith(window_prefix):
                calls_this_min += 1
        if calls_this_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _write_usage(usage)
        return None

    def _log(status_str, error_code=None, **extra):
        logs = _read_logs()
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000,9999)}",
            "endpoint": "describe_branch",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if extra:
            row.update(extra)
        logs.append(row)
        _write_logs(logs)

    # Validate types
    if not isinstance(project_id, str) or not project_id:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required", field="project_id")
    if not isinstance(branch_id, str) or not branch_id:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "branch_id is required", field="branch_id")
    if database_name is not None and not isinstance(database_name, str):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "database_name must be a string", field="database_name")
    if schema_name is not None and not isinstance(schema_name, str):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "schema_name must be a string", field="schema_name")
    if include_views is not None and not isinstance(include_views, bool):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_views must be boolean", field="include_views")
    if include_functions is not None and not isinstance(include_functions, bool):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_functions must be boolean", field="include_functions")

    lim = _check_limits_and_bump()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    projects = _load("projects.json")
    branches = _load("branches.json")
    execs = _load("sql_executions.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(branches, list):
        branches = []
    if not isinstance(execs, list):
        execs = []

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj or prj.get("deleted_at") is not None or prj.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found", field="project_id")

    br = next((b for b in branches if isinstance(b, dict) and b.get("id") == branch_id), None)
    if not br or br.get("project_id") != project_id or br.get("deleted_at") is not None or br.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Branch not found for project", field="branch_id")
    if br.get("status") != "ready":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Branch must be ready to describe", rule="describe_branch requires branch.status='ready'")

    # Offline "tree view": derive from successful SQL statements and include requested scopes.
    dbs = set()
    schemas = set()
    tables = set()
    views = set()
    functions = set()

    # Default database if not provided: infer from executions, else "neondb"
    if database_name is None:
        for ex in reversed(execs[-500:]):
            if isinstance(ex, dict) and ex.get("project_id") == project_id and ex.get("branch_id") == branch_id and isinstance(ex.get("database_name"), str):
                database_name = ex.get("database_name")
                break
        if database_name is None:
            database_name = "neondb"

    dbs.add(database_name)
    # infer basic objects from CREATE statements
    for ex in execs[-2000:]:
        if not isinstance(ex, dict):
            continue
        if ex.get("project_id") != project_id or ex.get("branch_id") != branch_id or ex.get("database_name") != database_name:
            continue
        if ex.get("status") != "succeeded":
            continue
        stmts = ex.get("statements")
        if not isinstance(stmts, list):
            continue
        for s in stmts:
            if not isinstance(s, str):
                continue
            sl = s.strip().lower()
            if sl.startswith("create schema"):
                parts = sl.split()
                if len(parts) >= 3:
                    sch = parts[2].strip('"').strip(";")
                    schemas.add(sch)
            if "create table" in sl:
                idx = sl.find("create table")
                rest = sl[idx + len("create table"):].strip()
                if rest.startswith("if not exists"):
                    rest = rest[len("if not exists"):].strip()
                token = rest.split()[0].strip('"')
                if "." in token:
                    sch, tbl = token.split(".", 1)
                else:
                    sch, tbl = "public", token
                schemas.add(sch)
                tables.add((sch, tbl))
            if include_views and "create view" in sl:
                idx = sl.find("create view")
                rest = sl[idx + len("create view"):].strip()
                token = rest.split()[0].strip('"')
                if "." in token:
                    sch, vw = token.split(".", 1)
                else:
                    sch, vw = "public", token
                schemas.add(sch)
                views.add((sch, vw))
            if include_functions and "create function" in sl:
                idx = sl.find("create function")
                rest = sl[idx + len("create function"):].strip()
                token = rest.split("(")[0].strip().strip('"')
                if "." in token:
                    sch, fn = token.split(".", 1)
                else:
                    sch, fn = "public", token
                schemas.add(sch)
                functions.add((sch, fn))

    if not schemas:
        schemas.add("public")

    if schema_name is not None:
        schemas = {s for s in schemas if s == schema_name}
        tables = {t for t in tables if t[0] == schema_name}
        views = {v for v in views if v[0] == schema_name}
        functions = {fn for fn in functions if fn[0] == schema_name}

    tree = {
        "project_id": project_id,
        "branch_id": branch_id,
        "database_name": database_name,
        "schemas": [],
    }
    for sch in sorted(list(schemas)):
        node = {
            "schema_name": sch,
            "tables": [{"schema_name": sch, "table_name": t[1]} for t in sorted([t for t in tables if t[0] == sch], key=lambda x: x[1])],
        }
        if include_views:
            node["views"] = [{"schema_name": sch, "view_name": v[1]} for v in sorted([v for v in views if v[0] == sch], key=lambda x: x[1])]
        if include_functions:
            node["functions"] = [{"schema_name": sch, "function_name": f[1]} for f in sorted([f for f in functions if f[0] == sch], key=lambda x: x[1])]
        tree["schemas"].append(node)

    _log("ok")
    return {"branch": br, "tree": tree}

def delete_branch(project_id, branch_id, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _read_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []
    def _write_logs(logs):
        _save("request_logs.json", logs)
    def _read_usage():
        usage = _load("usage.json")
        return usage if isinstance(usage, dict) else {}
    def _write_usage(usage):
        _save("usage.json", usage)
    def _check_limits_and_bump():
        logs = _read_logs()
        usage = _read_usage()
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        day = now[:10]
        if neon.get("day") != day:
            neon["day"] = day
            neon["calls_today"] = 0
        window_prefix = now[:16]
        calls_this_min = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str) and ts.startswith(window_prefix):
                calls_this_min += 1
        if calls_this_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _write_usage(usage)
        return None
    def _log(status_str, error_code=None, **extra):
        logs = _read_logs()
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000,9999)}",
            "endpoint": "delete_branch",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        row.update(extra or {})
        logs.append(row)
        _write_logs(logs)

    limit_err = _check_limits_and_bump()
    if limit_err:
        _log("error", error_code=limit_err["error"]["code"])
        return limit_err

    try:
        if not isinstance(project_id, str) or not re.match(r"^neon_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
            e = _err("VALIDATION_ERROR", "Invalid project_id.", field="project_id")
            _log("error", error_code=e["error"]["code"])
            return e
        if not isinstance(branch_id, str) or not re.match(r"^neon_br_[0-9A-HJKMNP-TV-Z]{10,}$", branch_id):
            e = _err("VALIDATION_ERROR", "Invalid branch_id.", field="branch_id")
            _log("error", error_code=e["error"]["code"])
            return e

        projects = _load("projects.json")
        branches = _load("branches.json")
        endpoints = _load("database_endpoints.json")
        if not isinstance(projects, list): projects = []
        if not isinstance(branches, list): branches = []
        if not isinstance(endpoints, list): endpoints = []

        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not prj or prj.get("deleted_at") is not None:
            e = _err("NOT_FOUND", "Project not found.", field="project_id")
            _log("error", error_code=e["error"]["code"])
            return e

        br = next((b for b in branches if isinstance(b, dict) and b.get("id") == branch_id), None)
        if not br or br.get("deleted_at") is not None:
            e = _err("NOT_FOUND", "Branch not found.", field="branch_id")
            _log("error", error_code=e["error"]["code"])
            return e
        if br.get("project_id") != project_id:
            e = _err("NOT_FOUND", "Branch not found for project.", field="branch_id")
            _log("error", error_code=e["error"]["code"])
            return e

        if br.get("is_default") is True:
            e = _err("CONFLICT", "Cannot delete default branch.", field="branch_id", rule="delete_branch is forbidden if branches.is_default=true")
            _log("error", error_code=e["error"]["code"])
            return e

        # if already deleted, return NOT_FOUND per mutation "no success without effect"
        if br.get("status") == "deleted":
            e = _err("NOT_FOUND", "Branch already deleted.", field="branch_id")
            _log("error", error_code=e["error"]["code"])
            return e

        # transitions: ready/creating/error -> deleting -> deleted
        allowed_to_deleting = {"creating", "ready", "error"}
        if br.get("status") not in allowed_to_deleting and br.get("status") != "deleting":
            e = _err("INVALID_TRANSITION", "Branch cannot be deleted from its current status.", field="branch_id")
            _log("error", error_code=e["error"]["code"])
            return e

        changed = False
        if br.get("status") != "deleting":
            br["status"] = "deleting"
            br["updated_at"] = now
            changed = True

        # associated endpoints -> deleted
        for ep in endpoints:
            if not isinstance(ep, dict):
                continue
            if ep.get("project_id") == project_id and ep.get("branch_id") == branch_id and ep.get("status") != "deleted":
                ep["status"] = "deleted"
                ep["updated_at"] = now
                changed = True

        if not changed:
            e = _err("NOT_FOUND", "No deletable resources found.", field="branch_id")
            _log("error", error_code=e["error"]["code"])
            return e

        # finalize delete
        br["status"] = "deleted"
        br["deleted_at"] = now
        br["updated_at"] = now
        _save("database_endpoints.json", endpoints)
        _save("branches.json", branches)

        _log("success")
        return {"branch": br}
    except Exception as e:
        err = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
        _log("error", error_code=err["error"]["code"])
        return err

