            candidates = [e for e in candidates if e.get("project_id") == project_id]
        if branch_id is not None:
            candidates = [e for e in candidates if e.get("branch_id") == branch_id]
        if database_name is not None:
            candidates = [e for e in candidates if e.get("database_name") == database_name]
        if not candidates:
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No available endpoint could be resolved for connection string", rule="endpoint must be available and branch ready")
        ep = sorted(candidates, key=lambda x: (x.get("updated_at") or "", x.get("created_at") or ""), reverse=True)[0]
        # resolve branch/project from endpoint if missing
        branch_id = branch_id or ep.get("branch_id")
        project_id = project_id or ep.get("project_id")
        if prj is None and project_id is not None:
            prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if br is None and branch_id is not None:
            br = next((b for b in branches if isinstance(b, dict) and b.get("id") == branch_id), None)
            if br and br.get("status") != "ready":
                _log("error", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Branch must be ready", rule="get_connection_string requires branch.status='ready'")

    # Determine role/database/ssl
    user = role or ep.get("default_role") or "postgres"
    db = database_name or ep.get("database_name") or "neondb"
    ssl = ssl_mode or ep.get("ssl_mode") or "require"

    # Must not return secrets; include_password ignored (no secrets store provided)
    # Build DSN
    user_enc = urllib.parse.quote(user, safe="")
    host = ep.get("host")
    port = ep.get("port")
    if not host or not port:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Endpoint is missing host/port", rule="database_endpoints must include host/port")

    dsn = f"postgresql://{user_enc}@{host}:{int(port)}/{urllib.parse.quote(db, safe='')}"
    params = {"sslmode": ssl}
    dsn_with_params = dsn + "?" + urllib.parse.urlencode(params)

    _log("ok")
    return {
        "connection": {
            "project_id": project_id,
            "branch_id": branch_id,
            "endpoint_id": ep.get("id"),
            "host": host,
            "port": int(port),
            "database": db,
            "role": user,
            "ssl_mode": ssl,
            "dsn": dsn_with_params,
            "includes_password": False,
        }
    }

def provision_neon_auth(project_id, provider, stack_project_id, stack_env=None, callback_urls=None, secrets_ref=None, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000,9999)}",
            "endpoint": "provision_neon_auth",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            usage = {}
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        if neon.get("day") != now[:10]:
            neon["day"] = now[:10]
            neon["calls_today"] = 0
        window_prefix = now[:16]
        calls_this_min = 0
        for r in logs[-5000:]:
            if isinstance(r, dict):
                ts = r.get("timestamp") or r.get("ts")
                if isinstance(ts, str) and ts.startswith(window_prefix):
                    calls_this_min += 1
        if calls_this_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _save("usage.json", usage)
        return None

    lim_err = _check_limits()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    if not isinstance(project_id, str) or not re.match(r"^neon_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log("error", "VALIDATION_ERROR", field="project_id")
        return _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
    if provider != "stack":
        _log("error", "VALIDATION_ERROR", field="provider")
        return _err("VALIDATION_ERROR", "provider must be 'stack'.", field="provider")
    if not isinstance(stack_project_id, str) or not stack_project_id.strip():
        _log("error", "VALIDATION_ERROR", field="stack_project_id")
        return _err("VALIDATION_ERROR", "stack_project_id is required.", field="stack_project_id")
    if stack_env is not None and not isinstance(stack_env, str):
        _log("error", "VALIDATION_ERROR", field="stack_env")
        return _err("VALIDATION_ERROR", "stack_env must be a string.", field="stack_env")
    if callback_urls is None or not isinstance(callback_urls, list) or len(callback_urls) == 0:
        _log("error", "VALIDATION_ERROR", field="callback_urls")
        return _err("VALIDATION_ERROR", "callback_urls must be a non-empty array.", field="callback_urls")
    for u in callback_urls:
        if not isinstance(u, str) or not u.strip():
            _log("error", "VALIDATION_ERROR", field="callback_urls")
            return _err("VALIDATION_ERROR", "callback_urls must contain only non-empty strings.", field="callback_urls")
    if secrets_ref is not None and not isinstance(secrets_ref, str):
        _log("error", "VALIDATION_ERROR", field="secrets_ref")
        return _err("VALIDATION_ERROR", "secrets_ref must be a string.", field="secrets_ref")

    projects = _load("projects.json")
    integrations = _load("auth_integrations.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(integrations, list):
        integrations = []

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id and p.get("deleted_at") is None), None)
    if not proj:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    # create/update exactly one row per (project, provider)
    integ = next((a for a in integrations if isinstance(a, dict) and a.get("project_id") == project_id and a.get("provider") == "stack"), None)

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id():
        existing = {r.get("id") for r in integrations if isinstance(r, dict)}
        for _ in range(1000):
            cand = "neon_auth_" + "".join(random.choice(alphabet) for _ in range(26))
            if cand not in existing:
                return cand
        return "neon_auth_" + "".join(random.choice(alphabet) for _ in range(30))

    if integ is None:
        integ = {
            "id": _new_id(),
            "project_id": project_id,
            "provider": "stack",
            "stack_project_id": None,
            "stack_env": None,
            "callback_urls": None,
            "secrets_ref": None,
            "status": "provisioning",
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        integrations.append(integ)

    # transition to provisioning
    cur = integ.get("status")
    allowed = {
        "provisioning": ("active", "error"),
        "active": ("disabled", "error"),
        "error": ("provisioning", "disabled"),
        "disabled": ("provisioning",),
    }
    if cur not in allowed:
        cur = "error"
        integ["status"] = "error"
    if "provisioning" not in allowed.get(cur, ()) and cur != "provisioning":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot set integration to provisioning from '{cur}'.")

    integ["status"] = "provisioning"
    integ["stack_project_id"] = stack_project_id.strip()
    integ["stack_env"] = stack_env
    integ["callback_urls"] = callback_urls
    if secrets_ref is not None:
        integ["secrets_ref"] = secrets_ref
    integ["last_error"] = None
    integ["updated_at"] = now
    _save("auth_integrations.json", integrations)

    # transition to active only if stack_project_id and secrets_ref are present
    if integ.get("stack_project_id") and integ.get("secrets_ref"):
        if "active" in allowed.get("provisioning", ()):
            integ["status"] = "active"
            integ["updated_at"] = now
            _save("auth_integrations.json", integrations)

    _log("ok")
    return {"auth_integration": integ}

def update_project(project_id, name=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, credential_id=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "service": "neon",
            "endpoint": "update_project",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_code,
            "credential_id": credential_id,
            "details": details or {}
        })
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(project_id, str) or not re.match(r"^neon_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log("VALIDATION_ERROR", details={"field": "project_id"})
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")

    if name is not None and not isinstance(name, str):
        _log("VALIDATION_ERROR", details={"field": "name"})
        return _err("VALIDATION_ERROR", "Invalid name type; expected string.", field="name")

    if status is not None:
        if not isinstance(status, str):
            _log("VALIDATION_ERROR", details={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status type; expected string.", field="status")
        if status not in ("deleting",):
            _log("VALIDATION_ERROR", details={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status value.", field="status", allowed=["deleting"])

    if name is None and status is None:
        _log("VALIDATION_ERROR", details={"reason": "no_mutations"})
        return _err("VALIDATION_ERROR", "No fields to update. Provide at least one of: name, status.")

    projects = _load("projects.json")
    branches = _load("branches.json")
    endpoints = _load("database_endpoints.json")

    if not isinstance(projects, list):
        projects = []
    if not isinstance(branches, list):
        branches = []
    if not isinstance(endpoints, list):
        endpoints = []

    proj_idx = None
    for i, p in enumerate(projects):
        if isinstance(p, dict) and p.get("id") == project_id:
            proj_idx = i
            break

    if proj_idx is None:
        _log("NOT_FOUND", details={"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.")

    project = projects[proj_idx]

    # Visibility rule: cannot update deleted projects (unless internal; not modeled)
    if project.get("deleted_at") is not None or project.get("status") == "deleted":
        _log("NOT_FOUND", details={"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.")

    # Name uniqueness constraint: unique(account_id, name) WHERE deleted_at IS NULL
    if name is not None:
        new_name = name.strip()
        if new_name == "":
            _log("VALIDATION_ERROR", details={"field": "name"})
            return _err("VALIDATION_ERROR", "Project name cannot be empty.", field="name")
        acct = project.get("account_id")
        for p in projects:
            if not isinstance(p, dict):
                continue
            if p.get("id") == project_id:
                continue
            if p.get("account_id") == acct and (p.get("deleted_at") is None) and p.get("name") == new_name:
                _log("CONFLICT", details={"field": "name"})
                return _err("CONFLICT", "A project with this name already exists in this account.", field="name")
        project["name"] = new_name

    # Status update: only caller-driven transition is to request deletion (deleting)
    if status is not None:
        curr = project.get("status")
        allowed = {
            "provisioning": ["active", "error", "deleting"],
            "active": ["deleting", "error"],
            "error": ["deleting"],
            "deleting": ["deleted"],
            "deleted": []
        }
        if status == "deleting":
            if curr not in allowed or "deleting" not in allowed.get(curr, []):
                _log("INVALID_TRANSITION", details={"from": curr, "to": "deleting"})
                return _err("INVALID_TRANSITION", f"Cannot transition project from {curr!r} to 'deleting'.",
                            from_status=curr, to_status="deleting")

            # Apply delete_project semantics: set deleting then deleted and soft-delete branches and endpoints
            project["status"] = "deleting"
            project["updated_at"] = now
            # Immediately finish deletion (no async engine here)
            project["status"] = "deleted"
            project["deleted_at"] = now
            project["updated_at"] = now

            # Soft-delete branches, respecting lifecycle transitions
            for b in branches:
                if not isinstance(b, dict):
                    continue
                if b.get("project_id") != project_id:
                    continue
                b_status = b.get("status")
                br_allowed = {
                    "creating": ["ready", "error", "deleting"],
                    "ready": ["deleting", "error"],
                    "error": ["deleting"],
                    "deleting": ["deleted"],
                    "deleted": []
                }
                # Drive to deleted if possible
                if b_status != "deleted":
                    if "deleting" in br_allowed.get(b_status, []):
                        b["status"] = "deleting"
                        b["updated_at"] = now
                    # finalize deletion if deleting allowed to deleted (or already deleting)
                    if b.get("status") == "deleting" and "deleted" in br_allowed.get("deleting", []):
                        b["status"] = "deleted"
                        b["deleted_at"] = now
                        b["updated_at"] = now
                    elif b.get("status") != "deleted":
                        # If branch is in an unknown/illegal state, mark error then delete not allowed by rules; treat as invalid transition
                        _log("INVALID_TRANSITION", details={"branch_id": b.get("id"), "status": b_status})
                        return _err("INVALID_TRANSITION", "Cannot delete project because a branch is in an invalid state.",
                                    branch_id=b.get("id"), branch_status=b_status)

            # Endpoints: transition to deleted
            ep_allowed = {
                "provisioning": ["available", "unavailable", "deleted"],
                "available": ["unavailable", "deleted"],
                "unavailable": ["available", "deleted"],
                "deleted": []
            }
            for e in endpoints:
                if not isinstance(e, dict):
                    continue
                if e.get("project_id") != project_id:
                    continue
                es = e.get("status")
                if es == "deleted":
                    continue
                if "deleted" not in ep_allowed.get(es, []):
                    _log("INVALID_TRANSITION", details={"endpoint_id": e.get("id"), "status": es})
                    return _err("INVALID_TRANSITION", "Cannot delete project because an endpoint is in an invalid state.",
                                endpoint_id=e.get("id"), endpoint_status=es)
                e["status"] = "deleted"
                e["updated_at"] = now

            # When project becomes deleted, default_branch_id can remain, but must not violate active constraint
            # (active constraint not relevant for deleted)

            _save("branches.json", branches)
            _save("database_endpoints.json", endpoints)

        else:
            _log("VALIDATION_ERROR", details={"field": "status"})
            return _err("VALIDATION_ERROR", "Only status='deleting' may be requested by callers.", field="status")

    # Ensure constraint: status != 'active' OR default_branch_id IS NOT NULL
    if project.get("status") == "active" and not project.get("default_branch_id"):
        _log("CONFLICT", details={"constraint": "active_requires_default_branch"})
        return _err("CONFLICT", "Active projects must have a default_branch_id.", constraint="active_requires_default_branch")

    project["updated_at"] = now
    projects[proj_idx] = project
    _save("projects.json", projects)

    _log("OK", details={"project_id": project_id})
    return {"project": project}

def list_branches(project_id, status=None, parent_branch_id=None, is_temporary=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, random, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _read_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _write_logs(logs):
        _save("request_logs.json", logs)

    def _read_usage():
        usage = _load("usage.json")
        return usage if isinstance(usage, dict) else {}

    def _write_usage(usage):
        _save("usage.json", usage)

    def _check_limits_and_bump():
        logs = _read_logs()
        usage = _read_usage()
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        day = now[:10]
        if neon.get("day") != day:
            neon["day"] = day
            neon["calls_today"] = 0

        window_prefix = now[:16]
        calls_this_min = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str) and ts.startswith(window_prefix):
                calls_this_min += 1
        if calls_this_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _write_usage(usage)
        return None

    def _log(status_str, error_code=None, **extra):
        logs = _read_logs()
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000,9999)}",
            "endpoint": "list_branches",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if extra:
            row.update(extra)
        logs.append(row)
        _write_logs(logs)

    if not isinstance(project_id, str) or not project_id:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required", field="project_id")

    allowed_status = {"creating", "ready", "deleting", "deleted", "error"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(list(allowed_status)))

    if parent_branch_id is not None and not isinstance(parent_branch_id, str):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_branch_id must be a string", field="parent_branch_id")

    if is_temporary is not None and not isinstance(is_temporary, bool):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_temporary must be boolean", field="is_temporary")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    allowed_sort = {"created_at", "updated_at", "name", None}
    if sort not in allowed_sort:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=sorted([s for s in allowed_sort if s]))

    allowed_order = {"asc", "desc", None}
    if order not in allowed_order:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order", field="order", allowed=["asc", "desc"])

    lim = _check_limits_and_bump()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    projects = _load("projects.json")
    branches = _load("branches.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(branches, list):
        branches = []

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj or prj.get("deleted_at") is not None or prj.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found", field="project_id")

    rows = [b for b in branches if isinstance(b, dict) and b.get("project_id") == project_id]
    if status is not None:
        rows = [b for b in rows if b.get("status") == status]
    if parent_branch_id is not None:
        rows = [b for b in rows if b.get("parent_branch_id") == parent_branch_id]
    if is_temporary is not None:
        rows = [b for b in rows if b.get("is_temporary") is is_temporary]

    # sort
    sfield = sort or "created_at"
    reverse = (order == "desc")
    rows.sort(key=lambda r: (r.get(sfield) or "", r.get("id") or ""), reverse=reverse)

    # cursor pagination: base64 offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        try:
            dec = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(dec.decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {"branches": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

def list_database_endpoints(project_id, branch_id=None, database_name=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, random, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0233000" if __import__("os").path.isdir("./environment_mix/0233000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _read_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _write_logs(logs):
        _save("request_logs.json", logs)

    def _read_usage():
        usage = _load("usage.json")
        return usage if isinstance(usage, dict) else {}

    def _write_usage(usage):
        _save("usage.json", usage)

    def _check_limits_and_bump():
        logs = _read_logs()
        usage = _read_usage()
        neon = usage.get("neon")
        if not isinstance(neon, dict):
            neon = {}
        quota_per_day = int(neon.get("quota_per_day", 10000))
        rate_per_min = int(neon.get("rate_limit_per_minute", 120))
        day = now[:10]
        if neon.get("day") != day:
            neon["day"] = day
            neon["calls_today"] = 0

        window_prefix = now[:16]
        calls_this_min = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("ts")
            if isinstance(ts, str) and ts.startswith(window_prefix):
                calls_this_min += 1
        if calls_this_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if int(neon.get("calls_today", 0)) >= quota_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        neon["calls_today"] = int(neon.get("calls_today", 0)) + 1
        usage["neon"] = neon
        _write_usage(usage)
        return None

    def _log(status_str, error_code=None, **extra):
        logs = _read_logs()
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000,9999)}",
            "endpoint": "list_database_endpoints",
            "status": status_str,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if extra:
            row.update(extra)
        logs.append(row)
        _write_logs(logs)

    if not isinstance(project_id, str) or not project_id:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required", field="project_id")
    if branch_id is not None and not isinstance(branch_id, str):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "branch_id must be a string", field="branch_id")
    if database_name is not None and not isinstance(database_name, str):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "database_name must be a string", field="database_name")

    allowed_status = {"provisioning", "available", "unavailable", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(list(allowed_status)))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    allowed_sort = {"created_at", "updated_at", None}
    if sort not in allowed_sort:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=["created_at", "updated_at"])

    allowed_order = {"asc", "desc", None}
    if order not in allowed_order:
        lim = _check_limits_and_bump()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order", field="order", allowed=["asc", "desc"])

    lim = _check_limits_and_bump()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    projects = _load("projects.json")
    endpoints = _load("database_endpoints.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(endpoints, list):
        endpoints = []

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj or prj.get("deleted_at") is not None or prj.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found", field="project_id")

    rows = [e for e in endpoints if isinstance(e, dict) and e.get("project_id") == project_id]
    if branch_id is not None:
        rows = [e for e in rows if e.get("branch_id") == branch_id]
    if database_name is not None:
        rows = [e for e in rows if e.get("database_name") == database_name]
    if status is not None:
        rows = [e for e in rows if e.get("status") == status]

    # sort
    sfield = sort or "created_at"
    reverse = (order == "desc")
    rows.sort(key=lambda r: (r.get(sfield) or "", r.get("id") or ""), reverse=reverse)

    # cursor offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        try:
            dec = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(dec.decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {"endpoints": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}
